import h5py, numpy as np
from scipy.special import softmax
runs={
 "speedups (prod default -1..0.4, 0..6)":"results/quiescent-test-set-speedups-2026-10-01/run/fits/fit/210210-M1_210210/ceridwen_result.h5",
 "kcbump-wide (-3..0.4, 0..12)":"results/m1-210210-kcbump-wide-2026-09-29/run/fits/wide/210210-M1_210210/ceridwen_result.h5",
 "neb_eline_ca_nohe_zevo (-3..0.4, 0..12)":"results/m1-210210-neb-eline-ca-nohe-zevo-2026-09-30/run/fits/neb_eline_ca_nohe_zevo/210210-M1_210210/ceridwen_result.h5",
}
def wq(x,w,q):
    i=np.argsort(x); c=np.cumsum(w[i]); return np.interp(q,c/c[-1],x[i])
for k,p in runs.items():
    try: f=h5py.File(p)
    except Exception as e: print(k,e); continue
    w=softmax(f["samples/log_weights"][:])
    print("==",k)
    for n in ["diffuse_tau_noll","diffuse_delta","diffuse_Ebump","dust_ratio","zh_beta_unit","log_f_calib","logmass","Z","afe"]:
        x=f["samples/"+n][:]
        print(f"  {n:18s} 2.5/16/50/84/97.5: "+" ".join(f"{v:8.3f}" for v in wq(x,w,[.025,.16,.5,.84,.975])))
EOF",
  "description": "Weighted posterior quantiles of dust parameters per fit"
}

